//! An inner outline with a fill or a lane type is an area of its own, as
//! well as a hole in the outline round it.
//!
//! `inner_outlines.xodr` is generated by `scenariogeneration` (see
//! `inner_outlines.py`). Its road 1 is a flat straight from the origin
//! heading +X, so a road station `(s, t)` is the point `(s, t)`.

use xodr::{
    load_file_with_provenance, Corner, LaneType, Object, ObjectProvenance, Provenance, RoadNetwork,
    Shape,
};

const FIXTURE: &str = concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/tests/data/inner_outlines.xodr"
);

fn load() -> (RoadNetwork, Provenance) {
    load_file_with_provenance(FIXTURE).expect("import")
}

/// Every object the island baked to, with its provenance, in order.
fn island<'a>(
    net: &'a RoadNetwork,
    prov: &'a Provenance,
) -> Vec<(&'a Object, &'a ObjectProvenance)> {
    prov.objects
        .iter()
        .filter(|p| p.od_id == "1")
        .map(|p| (net.object(p.object).expect("baked"), p))
        .collect()
}

fn outline(object: &Object) -> (&[Corner], &[Vec<Corner>]) {
    match &object.shape {
        Shape::Outline { corners, holes, .. } => (corners, holes),
        other => panic!("not an outline: {other:?}"),
    }
}

/// The `(s, t)` range of a ring of corners, as `(s0, s1, t0, t1)`.
fn bounds(corners: &[Corner]) -> (f32, f32, f32, f32) {
    let s = corners.iter().map(|c| c.base.x);
    let t = corners.iter().map(|c| c.base.y);
    (
        s.clone().fold(f32::INFINITY, f32::min),
        s.fold(f32::NEG_INFINITY, f32::max),
        t.clone().fold(f32::INFINITY, f32::min),
        t.fold(f32::NEG_INFINITY, f32::max),
    )
}

#[test]
fn each_filled_inner_outline_is_an_area_of_its_own() {
    let (net, prov) = load();
    let areas: Vec<_> = island(&net, &prov)
        .into_iter()
        .map(|(o, p)| {
            (
                bounds(outline(o).0),
                p.fill_type.as_str(),
                p.outline_lane_type,
            )
        })
        .collect();
    assert_eq!(
        areas,
        [
            ((10.0, 30.0, -6.0, -2.0), "grass", None),
            ((12.0, 16.0, -5.0, -3.0), "cobble", Some(LaneType::Sidewalk)),
            ((22.0, 26.0, -5.0, -3.0), "concrete", None),
            ((40.0, 42.0, -5.0, -3.0), "gravel", None),
            ((27.0, 29.0, -5.0, -3.0), "", Some(LaneType::Driving)),
        ]
    );
}

#[test]
fn every_inner_outline_the_outer_one_encloses_is_cut_out_of_it() {
    let (net, prov) = load();
    let (outer, _) = island(&net, &prov)[0];
    let holes: Vec<_> = outline(outer).1.iter().map(|h| bounds(h)).collect();
    assert_eq!(
        holes,
        [
            (12.0, 16.0, -5.0, -3.0),
            (18.0, 20.0, -5.0, -3.0),
            (22.0, 26.0, -5.0, -3.0),
            (27.0, 29.0, -5.0, -3.0),
        ]
    );
}

#[test]
fn an_inner_area_keeps_its_own_markings_and_borders() {
    let (net, prov) = load();
    let parts = island(&net, &prov);
    let (outer, _) = parts[0];
    let (walk, _) = parts[1];
    assert!(outer.markings.is_empty() && outer.borders.is_empty());
    assert_eq!(walk.markings.len(), 1);
    let [kerb] = &walk.borders[..] else {
        panic!("one border: {:?}", walk.borders);
    };
    assert_eq!(kerb.pieces.len(), 4);
}
